command:
if (!game.user.isGM) return ui.notifications.warn('Change Allegiance(s) is GM-only.');

const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (!units.length) return ui.notifications.warn('Select one or more units first.');

const OWNER = CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
const OWNABLE_ROLES = ['Retainer', 'Ally'];
const ROLES = ['Retainer', 'Neutral', 'Enemy', 'Ally'];
const players = game.users.filter(user => !user.isGM);
const escape = foundry.utils.escapeHTML;

const roleOptions = ROLES.map(role => `<option value="${role}">${role}</option>`).join('');
const ownerOptions = [
  '<option value="">No owner (GM only)</option>',
  ...players.map(user => `<option value="${user.id}">${escape(user.name)}</option>`)
].join('');
const roster = units.map(token => `${escape(token.actor.name)} (${token.actor.system?.faction?.role ?? 'Neutral'})`)
  .join(', ');

const choice = await foundry.applications.api.DialogV2.wait({
  window: { title: 'Change Allegiance(s)' },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 460 },
  content: `
    <div class="ed-container">
      <div class="ed-section ed-section--highlight">
        <p class="ed-description">${roster}</p>
      </div>
      <div class="ed-section">
        <label class="ed-label" for="emblem-allegiance-role">Faction role</label>
        <select id="emblem-allegiance-role" class="ed-input" name="role">${roleOptions}</select>
      </div>
      <div class="ed-section">
        <label class="ed-label" for="emblem-allegiance-owner">Owned by</label>
        <select id="emblem-allegiance-owner" class="ed-input" name="owner">${ownerOptions}</select>
        <p class="ed-description">A player may own a Retainer or an Ally only.</p>
      </div>
    </div>`,
  buttons: [
    {
      action: 'apply',
      label: 'Change Allegiance',
      icon: 'fas fa-flag',
      default: true,
      callback: (event, button) => ({
        role: button.form.elements.role.value,
        owner: button.form.elements.owner.value
      })
    },
    { action: 'cancel', label: 'Cancel', callback: () => null }
  ],
  render: (event, dialog) => {
    const role = dialog.element.querySelector('[name="role"]');
    const owner = dialog.element.querySelector('[name="owner"]');
    const sync = () => {
      const ownable = OWNABLE_ROLES.includes(role.value);
      owner.disabled = !ownable;
      if (!ownable) owner.value = '';
    };
    role.addEventListener('change', sync);
    sync();
  },
  rejectClose: false
});

if (!choice || typeof choice !== 'object') return;
const grantOwner = OWNABLE_ROLES.includes(choice.role) ? choice.owner : '';

const changed = [];
const failures = [];
for (const token of units) {
  const actor = token.actor;
  const from = actor.system?.faction?.role ?? 'Neutral';
  const update = { 'system.faction.role': choice.role };
  if (grantOwner) update[`ownership.${grantOwner}`] = OWNER;
  if (choice.role === 'Retainer' && !actor.isToken) update['prototypeToken.actorLink'] = true;
  try {
    await actor.update(update);
    changed.push({ unit: actor.name, role: `${from} → ${choice.role}`, owner: grantOwner ? game.users.get(grantOwner)?.name : 'none' });
  } catch (err) {
    failures.push({ unit: actor.name, error: err.message });
    console.error(`emblem-rpg | Change Allegiance(s) failed for ${actor.name}:`, err);
  }
}

console.group(`emblem-rpg | Change Allegiance(s) — ${changed.length} unit(s) changed`);
if (changed.length) console.table(changed);
if (failures.length) console.table(failures);
console.groupEnd();

if (failures.length) ui.notifications.error(`Changed ${changed.length} unit(s); ${failures.length} failed, see console.`);
else ui.notifications.info(`${changed.length} unit(s) are now ${choice.role}${grantOwner ? `, owned by ${game.users.get(grantOwner)?.name}.` : '.'}`);
